/// Count how many results in `results` match `filter` and survive
/// the confidence floor, --only-poc and --limit-result-type in the selected tier model.
///
/// This is the findings tally behind `--limit`'s early stop, the deep-scan
/// findings cap, the multi-target ticker, and the REST/MCP live
/// `findings_so_far`. A finding `--min-confidence` will drop must not count
/// here, or `--limit 1 --min-confidence high` stops on an `R` and then
/// reports nothing.
pub(crate) fn count_matching_results(
    results: &[crate::scanning::result::Result],
    args: &ScanArgs,
) -> usize {
    if args.tier_model.as_deref() == Some("confidence") {
        return crate::cmd::scan::dedupe_ast_results_for_model(
            results.iter().collect(),
            args.tier_model.as_deref(),
        )
        .into_iter()
        .filter(|r| args.counts_toward_limit(r))
        .count();
    }
    results
        .iter()
        .filter(|r| args.counts_toward_limit(r))
        .count()
}

/// [`count_matching_results`] for `batch` as it is appended to `existing`,
/// counting an AST finding only when the report will not fold it into one
/// already counted: `dedupe_ast_results` keeps one finding per
/// `ast_dedup_key`, and every parameter's probe re-finds the same page-level
/// sink.
// Legacy counting retains its historical any-matching-copy rule. Confidence
// counting follows the selected winner, including replacements across batches.
pub(crate) fn count_new_matching_results(
    existing: &[crate::scanning::result::Result],
    batch: &[crate::scanning::result::Result],
    args: &ScanArgs,
) -> isize {
    if args.tier_model.as_deref() == Some("confidence")
        && batch
            .iter()
            .any(|r| crate::cmd::scan::ast_dedup_parts(r).is_some())
    {
        let before = count_matching_results(existing, args);
        let combined = existing.iter().chain(batch).collect();
        let after =
            crate::cmd::scan::dedupe_ast_results_for_model(combined, args.tier_model.as_deref())
                .into_iter()
                .filter(|r| args.counts_toward_limit(r))
                .count();
        return after as isize - before as isize;
    }
    let matches = |r: &&crate::scanning::result::Result| args.counts_toward_limit(r);
    // Borrowed keys: this runs under the results lock on every flush, so the
    // walk over `existing` must not allocate per result.
    use crate::cmd::scan::ast_dedup_parts as ast_key;
    let mut seen: Option<HashSet<(&str, &str, &str)>> = None;
    let mut added = 0;
    for r in batch.iter().filter(matches) {
        let Some(key) = ast_key(r) else {
            added += 1;
            continue;
        };
        let seen = seen.get_or_insert_with(|| {
            existing
                .iter()
                .filter(matches)
                .filter_map(ast_key)
                .collect()
        });
        if seen.insert(key) {
            added += 1;
        }
    }
    added
}

/// Per-target "a finding already landed for this injection point" sets, keyed
/// by [`found_param_key`].
struct FoundParams {
    reflection: HashSet<String>,
    dom: HashSet<String>,
}

/// Identity of a parameter *slot* for the [`FoundParams`] sets.
///
/// Keyed on the wire location and the wire-level name, not just the display
/// name: the same name routinely names two independent injection points on one
/// request — `?q=` in the query string *and* `q` in the POST body, or a `q`
/// cookie — and a finding at one says nothing about the other. Keying on
/// `Param::name` alone let the first slot that produced a finding suppress
/// every sibling slot: the reflection/DOM phases short-circuited and the
/// dispatch loop skipped the sibling's worker outright, so a vulnerable body
/// parameter was silently never reported (false negative).
///
/// `wire_name` is part of the key so nested-field synthetic params
/// (`qs[move_url]`, whose wire name is the parent `qs`) stay distinct from one
/// another exactly as they were under the old name-only key.
fn found_param_key(param: &Param) -> String {
    // `\u{1}` separator: not producible by a URL/header parameter name, so
    // concatenation cannot alias two different slots onto one key.
    //
    // A form field is sent to its form's action, so the same name posted to two
    // different actions is two slots too (discovery keeps both, see
    // `dedupe_reflection_params`); a finding at one must not skip the other.
    format!(
        "{:?}\u{1}{}\u{1}{}\u{1}{}",
        param.location,
        param.name,
        param.effective_wire_name(),
        param.form_action_url.as_deref().unwrap_or("")
    )
}

