    // walk over `existing` must not allocate per result.
    use crate::cmd::scan::ast_dedup_parts as ast_key;
    let mut seen: Option<HashSet<(&str, &str, &str)>> = None;
    let mut added = 0;
    for r in batch.iter().filter(matches) {
        let Some(key) = ast_key(r) else {
            added += 1;
