    /// HTTP-layer parameter name used when the payload must be inserted at a
    /// different name than this `Param.name`. Set when `name` is a synthetic
    /// nested-field display label (e.g. `qs[move_url]`) but the wire-level
    /// substitution targets the parent parameter (`qs`). When `None`, callers
    /// fall back to `name`.
    ///
    /// Currently honored in the `Location::Query` substitution paths
    /// (`build_injected_url`, `active_probe_param`). `Location::Body`,
    /// `Header`, `JsonBody`, `MultipartBody` still substitute by `name`
    /// because nested-field discovery (`infer_nested_pipelines`) only
    /// emits Query params today. Extend those branches before enabling
    /// nested discovery on other locations.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub wire_name: Option<String>,
    /// POST target URL resolved from form action attribute.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub form_action_url: Option<String>,
    /// Page URL where the form was discovered (for stored XSS verification).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub form_origin_url: Option<String>,
    /// Framework-specific innerHTML-style sink the marker landed inside
    /// during discovery: `"v-html"`, `"data-bind"`, `"ng-bind-html"`,
    /// `"dangerouslySetInnerHTML"`. When set, the reflection is rendered
    /// as raw HTML by the framework at runtime — entity-encoded
    /// payloads also execute because the browser decodes them at
    /// attribute-value parse time before innerHTML assignment. Used to
    /// upgrade the finding's `inject_type` label so users can tell
    /// framework-sink reflections apart from generic attribute echo.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub framework_sink: Option<String>,
    /// Special characters that reflect back only in *escaped* form — the server
    /// inserts a backslash before them (e.g. `"` → `\"`, the classic
    /// JS-string-escaping filter). Distinct from `valid_specials` (reflected
    /// raw) and `invalid_specials` (stripped/encoded): an escaped quote *is*
    /// present in the response but cannot break out raw, so payload synthesis
    /// uses a backslash-prefixed breakout (`\";…`) instead. Populated by the
    /// quote-escape probe in `active_probe_param` (issue #1072).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub escaped_specials: Option<Vec<char>>,
    /// Exact JS breakout closer computed from the *observed* inline-`<script>`
    /// source between the enclosing script's content start and this parameter's
    /// reflection point (issue #1073 follow-up). For a reflection nested inside
    /// e.g. `foo({ bar: [ "…" ] })` this carries `"]})` — the minimal sequence
    /// that closes the open string and every unbalanced `([{` to reach an
    /// executable statement position. Computed once at detection time (where the
    /// response body is available) via
    /// [`crate::payload::js_breakout::compute_js_breakout`] and consumed by
    /// payload synthesis, which emits the matching breakout *first* (highest
    /// confidence) ahead of the fixed depth-0–3 catalog. `None` when the
    /// reflection is not inside an inline `<script>` body, or when the observed
    /// prefix already sits at statement position (nothing to close) — in which
    /// case synthesis falls back to the fixed catalog exactly as before.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub js_breakout: Option<String>,
    /// True when the reflection is inside a string literal that directly reaches
    /// a JavaScript code-execution sink (e.g. `setTimeout("...", ...)` or
    /// `location = "javascript:..."`) without requiring a quote breakout.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub in_js_exec_sink: bool,
    /// A pre-scan probe already saw this parameter's markers come back.
    ///
    /// Set by [`active_probe_param`], the last stage before scanning, which
    /// sends `OPEN + specials + CLOSE` and reads the echo. The scan worker's
    /// Stage-0 probe asks the *same* question with the *same* markers, so when
    /// this is set it skips its request and takes the answer (one request per
    /// parameter, ~25% of the per-parameter cost on a reflecting target).
    ///
    /// One-directional on purpose: `false` never means "does not reflect", only
    /// "no probe has proved it does". The batched probe is dense with special
    /// characters, so a WAF can block it while the plain marker gets through —
    /// which is exactly why Stage 0 still runs in that case.
    ///
    /// Scan-internal despite being `pub` (the struct's other fields are too,
    /// and integration tests build `Param` literals): `#[serde(skip)]` keeps it
    /// off every output and API surface, and a param deserialized from one
    /// starts out `false`, i.e. gets the pre-existing behaviour.
    #[serde(default, skip)]
    pub marker_echoed: bool,
    /// Page slots (element attributes / text, CSS custom properties) that
    /// held the pre-scan probe's marker, when that probe echoed on a page with
    /// script. The AST phase reads it as proof that the page's JS reading
    /// those slots reads this parameter: Stage 0 is skipped when the probe
    /// echoed, and the attack response it analyses instead has usually broken
    /// out of the very slot it would need to prove. Scan-internal, like
    /// `marker_echoed`.
    #[serde(default, skip)]
    pub reflected_markup: Option<std::sync::Arc<crate::scanning::ast_dom_analysis::PageMarkup>>,
    /// XML response MIME for which the active probe reflected its marker but
    /// the body has no active namespace yet. The scan uses a small, namespaced
    /// XML payload set for this case rather than spending the full HTML catalog
    /// on a document that currently parses as inert XML.
    #[serde(default, skip)]
    pub xml_namespace_candidate: Option<String>,
    /// Explicitly distinguishes a cookie parameter from an HTTP header when
    /// both locations carry the same name. `None` preserves the legacy
    /// target-based inference for params created by older callers.
    #[serde(skip)]
    pub is_cookie: Option<bool>,
    /// Operator-facing filter verdict from the active probe, surfaced on
    /// findings (issue #1515). Separate from `valid_specials` /
    /// `invalid_specials`, which are tuned for recall (an entity-encoded echo
    /// counts as valid, a failed probe as all-invalid) and so misread as a
    /// verdict. `None` when the probe produced no trustworthy reading.
    #[serde(skip)]
    pub filter: Option<FilterFingerprint>,
}

/// How a parameter treated each probed special character, read from the
/// batched probe's reflected segment.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, schemars::JsonSchema)]
pub struct FilterFingerprint {
    /// Reflected raw.
    pub allowed: Vec<char>,
    /// Reflected only as an HTML entity or `%HH`.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub encoded: Vec<char>,
    /// Stripped, or forbidden by the transport.
    pub blocked: Vec<char>,
    /// Reflected only with a backslash in front.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub escaped: Vec<char>,
}

impl FilterFingerprint {
    /// Classify every `probe_chars` entry against the reflected `segment`.
    pub(crate) fn from_segment(segment: &str, probe_chars: &[char]) -> Self {
        static ENCODED: std::sync::LazyLock<regex::Regex> = std::sync::LazyLock::new(|| {
            regex::Regex::new(r"&#?[0-9A-Za-z]+;|%[0-9A-Fa-f]{2}").expect("static regex")
        });
        // Without the encoded sequences, so the `;` of `&lt;` is not a raw `;`.
        let raw = ENCODED.replace_all(segment, "");
        // Decode each sequence rather than match known spellings: servers emit
        // `&#039;`, `&#x27;`, `%3c`, ... for the same char.
        let encoded: Vec<char> = ENCODED
            .find_iter(segment)

item.aggregated_output:
    // path (`count_matching_results` in `accumulate`/`record_results`). Using
    // the raw length delta (`before - after`) would over-decrement whenever the
    // collapsed entries — always `R` duplicates — don't match
    // `--limit-result-type` (e.g. `V`/`A`): `findings_count` never counted them,
    // so subtracting them underflows the unsigned counter to ~usize::MAX and
    // poisons `limit_reached()` for the rest of a multi-target run (a silent,
    // hard-to-diagnose scan truncation).
    let before_matching = count_matching_results(&original, args);
    let collapsed = collapse_redundant_reflected(original, &target_key, &target_url_str);
    let after_matching = count_matching_results(&collapsed, args);
    *guard = collapsed;
    if after_matching < before_matching {
        findings_count.fetch_sub(before_matching - after_matching, Ordering::Relaxed);
    }
}

/// Outcome of a per-parameter scan phase. `Abort` means a global `--limit` was
/// reached mid-phase, so the worker stops immediately without running the
/// remaining phases. A `break`-style early exit (cancellation) instead yields
/// `Continue`, so later phases run their own cancellation checks.
///
/// Either way the caller flushes whatever the worker already batched. The
/// pre-refactor `return` discarded that batch instead, on the reasoning that
/// "the limit is already hit, the scan is winding down" — but `--limit` is a
/// *stop condition*, not an instruction to destroy evidence already confirmed
/// against the target, and the worker that aborts is rarely the one that
/// reached the cap. The discard is observable whenever the surviving tally
/// falls back under the limit before rendering, which `collapse_target_results`
/// does routinely (it decrements `findings_count` for every `R` a `V` covers):
/// the report then has room for the findings the abort threw away. Under a
/// limit the phase loops also flush before every check
/// (`ScanWorkerCtx::limit_reached_in_phase`), so an abort holds at most what
/// the current chunk confirmed. The CLI truncates to `--limit` again at render
/// time (`cmd::scan::output`); server/MCP jobs keep that small overshoot.
enum PhaseFlow {
    Continue,
    Abort,
}

/// Issue #1156 — recall-preserving DOM-phase early-exit budgets.
///
/// `run_dom_phase` only short-circuits when a payload actually *verifies* (`V`).
/// On a self-/canonical-link echo endpoint — one that reflects every payload but
/// in an inert (non-executable) context — that means the *entire* DOM payload
/// set is sent (measured at tens of thousands of requests for a single
/// parameter; see the issue). These budgets curtail that fan-out once the
/// endpoint has produced overwhelming evidence it will never verify, without
/// trimming the high-signal shapes.
///
/// `INERT_ECHO_BUDGET` is the cumulative count of payloads that were reflected
/// but inert (`reflected && !verified`).
///
/// Recall safety rests on two properties:
///
/// 1. **The budget only accrues on endpoints that hand our exact bytes back.**
///    `DomVerifyOutcome::reflected` is true for a byte-exact reflection *or* for
///    a pure escaped echo of the same bytes
///    (`check_reflection::is_escaped_echo`: the server emitted `&amp;lt;svg …`
///    / `%3Csvg%20…` for the whole payload). Both are proof the endpoint took
///    our payload and rendered it inertly.
///
///    A *sanitizing* endpoint (DOMPurify, whitelisting templates, …) is
///    excluded, because it **removes** markup rather than escaping it: the
///    payload never surfaces whole in any decoded view, so `is_escaped_echo` is
///    false and `inert_echo_count` does not advance. That is what keeps a late
///    whitelisted verifier (sanitizer-level3's `<a href=javascript:>`) from
///    being cut. The same gate abstains on truncated/partial echoes,
///    `+`→space-only form decoding, event-handler and URL-valued-attribute
///    contexts (where an escaped echo still executes), and on 4xx responses (a
///    WAF block page that echoes the payload is a block, not an inert echo —
///    see `BLOCKED_STREAK_LIMIT`).
///
///    Before escaped echoes were counted, a *uniformly escaping* endpoint — the
///    most common shape on the web — advanced this counter zero times, and the
///    phase ran its whole catalog against a body that can never verify
///    (measured: 5394 requests, 0 findings, on the `inert` perf-budget
///    scenario).
///
/// 2. **Every DOM-evidence kind is sampled before the budget can trip.** For the
///    unknown-context catalog the families are round-robin interleaved (see
///    `interleave_payload_families`), so any prefix — including the first
///    `INERT_ECHO_BUDGET` echoes — contains a representative of each evidence
///    kind: HTML-tag injection, event-handler/attribute breakout, mXSS,
///    DOM-clobbering, and `javascript:`/`data:` protocol-URL (the sole verifier
///    for URL-attribute sinks). Without the interleave the protocol/mXSS
///    families are appended last and would sit thousands of payloads past the
///    budget. Context-specific catalogs are already shape-diverse up front.
///
/// Given (1) and (2), 256 reflected-but-inert echoes with zero verifications is
/// overwhelming evidence of a uniformly-inert echo; the remaining payloads are
/// redundant sink-variations (`alert` vs `prompt`) and encoder-variants of
/// shapes that already failed, so cutting them is recall-neutral.
const INERT_ECHO_BUDGET: u32 = 256;

/// Cumulative count of *transformed-inert* echoes that ends the **reflection**
/// phase early.
///
/// The reflection phase mints an `R` on the first byte-exact reflection and its
/// `reflection_found_locally` short-circuit then stops the loop. But a
/// *uniformly-escaping* endpoint — the most common shape on the web — mints no
/// `R` at all: `classify_reflection` correctly demotes an escaped echo
/// (`&lt;svg …&gt;`, `%3Csvg…`) to `None`, so the short-circuit never trips and
/// the phase runs its **entire** catalog against a body that can never yield a
/// finding (measured: the reflection half of the `inert` perf-budget scenario).
///
/// This budget gives that case the same recall-preserving stop the DOM phase
/// already has. It accrues only on responses that are a *transformed-but-inert*
/// echo of our exact payload — `check_reflection::is_escaped_echo` returns true
/// — which by construction excludes sanitizer-stripped output (markup removed,
/// not escaped, so the payload never surfaces whole), truncated/partial echoes,
/// event-handler and URL-attribute landing sites (an escaped echo there
/// executes), and `+`→space-only form decoding. Callers additionally exclude
/// 4xx responses (a WAF block page that echoes the payload is a block, not an
/// inert echo — a later variant may bypass it) and non-renderable bodies (the
/// 3xx `Location:` stand-in).
///
/// Recall rests on the same diversity guarantee as `INERT_ECHO_BUDGET`: the
/// unknown-context reflection catalog is family-interleaved
/// (`get_fallback_reflection_payloads`), so a representative of every family —
/// including the `javascript:`/`data:` protocol payloads that are the sole
/// reflection-phase verifier for a URL-attribute sink — appears well within
/// this window. Disabled under `--deep-scan`. It only stops *launching* further
/// payloads; nothing about reporting classification changes.
const REFLECTION_INERT_ECHO_BUDGET: u32 = 256;

/// Issue #1156 — *consecutive* dead-server responses that end the DOM phase.
///
/// Scoped to **server errors (`status >= 500`) only**, deliberately *excluding*
/// 4xx WAF blocks (`403`/`406`/`429`): a payload *variant* can bypass a WAF
/// filter, so early-exiting on a 4xx block would risk cutting a working bypass
/// (those are handled by the reflection-path WAF backoff instead). A 5xx that
/// tells us nothing back is the server failing — no payload variant "bypasses"
/// it — so a long consecutive run is a safe, recall-neutral stop. A single
/// response that does not qualify resets the streak, so a transient blip cannot
/// abandon a recoverable parameter.
///
/// A 5xx that **echoes the payload** is explicitly *not* counted. That
/// combination is a framework development error page (Kemal, Werkzeug, Rails,
/// Symfony …), which renders the request path, query string, or an exception
/// message built from user input — one of the most common reflected-XSS sinks
/// there is, and a 500 by construction. Counting it lost the entire class:
/// after 64 payloads dalfox abandoned DOM verification and could only ever
/// report `[R]` for a parameter that `--deep-scan` verifies as `[V]`. Fan-out
/// on such an endpoint stays bounded by [`INERT_ECHO_BUDGET`], which is the
/// budget designed for "reflects everything, verifies nothing".
const BLOCKED_STREAK_LIMIT: u32 = 64;

/// *Consecutive* 3xx-redirect responses that end the DOM phase.
///
/// A redirect can never produce a DOM verification: browsers do not render a
/// 3xx response body (only `Location:` drives navigation), and DOM verification
/// never treats a `javascript:` / `data:` / reflected-`next=` `Location:` as
/// evidence (modern browsers refuse to execute those from a redirect header). So a DOM payload
/// sent to a redirecting response is guaranteed non-verifying, and a long run of
/// them is pure waste — the reflection phase already recorded any `R` the
/// `Location:` echo warrants.
///
/// Scoped **consecutive** (any non-3xx resets it, like [`BLOCKED_STREAK_LIMIT`])
/// so a *conditionally* redirecting endpoint — one that redirects for most
/// payloads but renders a 200 for a specific shape that dodges the redirect
/// rule — is never abandoned: the first 200 clears the streak and the phase
/// continues. The diverse interleave (#1156) means that non-redirecting shape,
/// if it exists, appears well within this window. `--deep-scan` disables it.
const REDIRECT_STREAK_LIMIT: u32 = 32;

/// True for statuses that signal the endpoint will not yield a DOM verification
/// *and* that no payload variant could turn around: any 5xx server error. 4xx
/// WAF blocks are intentionally excluded (see [`BLOCKED_STREAK_LIMIT`]); `0`
/// (request error) is likewise not blocking — a transient network error should
/// not, on its own, end the phase.
///
/// Status alone is not the whole test: see [`next_blocked_streak`], which
/// additionally spares a 5xx that reflected the payload.
fn is_blocking_dom_status(status: u16) -> bool {
    status >= 500
}

/// Fold one DOM response's `reflected` flag into the cumulative inert-echo
/// count. Cumulative (never resets on a non-reflecting response) so an endpoint
/// that reflects most-but-not-all payloads still converges on the budget. Pure
/// for unit testing.
fn next_inert_echo_count(prev: u32, reflected: bool) -> u32 {
    if reflected { prev + 1 } else { prev }
}

/// Fold one DOM response's status into the consecutive blocked streak: increment
/// on a blocking status, reset to 0 otherwise. The reset is what makes the
/// streak *consecutive* (one good response clears it), preserving recall on
/// intermittently-failing endpoints.
///
/// `reflected` spares the responses a 5xx status alone would condemn: a server
/// error that hands our payload back is a rendered error page, not a dead
/// server, and error pages are a first-class XSS sink (see
/// [`BLOCKED_STREAK_LIMIT`]). Pure for unit testing.
fn next_blocked_streak(prev: u32, status: u16, reflected: bool) -> u32 {
    if is_blocking_dom_status(status) && !reflected {
        prev + 1
    } else {
        0
    }
}

/// True for a 3xx redirect status, which structurally cannot DOM-verify
/// (see [`REDIRECT_STREAK_LIMIT`]).
fn is_redirect_dom_status(status: u16) -> bool {
    (300..400).contains(&status)
}

/// Fold one DOM response's status into the consecutive redirect streak:
/// increment on a 3xx, reset to 0 on anything else. The reset keeps it
/// *consecutive*, so a conditionally-redirecting endpoint is never abandoned on
/// a transient redirect. Pure for unit testing.
fn next_redirect_streak(prev: u32, status: u16) -> u32 {
    if is_redirect_dom_status(status) {
        prev + 1
    } else {
        0
    }
}

/// Decide whether the DOM phase should stop early given the signals accumulated
/// so far. Pure so it can be unit-tested without a live server. Disabled under
/// `--deep-scan` (the exhaustive mode that opts out of all fan-out trimming).
fn dom_phase_should_early_exit(
    deep_scan: bool,
    inert_echo_count: u32,
    blocked_streak: u32,
    redirect_streak: u32,
) -> bool {
    !deep_scan
        && (inert_echo_count >= INERT_ECHO_BUDGET
            || blocked_streak >= BLOCKED_STREAK_LIMIT
            || redirect_streak >= REDIRECT_STREAK_LIMIT)
}

/// Mutable per-parameter state shared across a single worker's probe,
/// reflection, DOM, and HPP phases.
#[derive(Default)]
struct ParamScanState {
    /// Findings batched locally, flushed to the shared vector once at the
    /// end of the worker (one lock acquisition instead of one per finding) —
    /// or per payload batch under a `--limit`, see `limit_reached_in_phase`.
    local_results: Vec<crate::scanning::result::Result>,
    /// AST findings already recorded for this param (dedup key set).
    ast_seen: HashSet<String>,
    /// AST DOM analysis runs at most once per param.
    ast_analysis_done: bool,
    /// Reflection already confirmed for this param locally — skip the
    /// remaining reflection payloads.
    reflection_found_locally: bool,
    /// DOM XSS already confirmed for this param locally — skip the
    /// remaining DOM payloads.
    dom_found_locally: bool,
    /// DOM verdicts the reflection phase already computed for a DOM payload it
    /// sent byte-for-byte (issue #1661). The DOM phase takes an entry instead of
    /// re-sending that request; the entry still feeds its early-exit budgets.
    /// Bounded by the DOM payload set, and a verified entry's body is trimmed
    /// to the evidence bound.
    dom_reuse: HashMap<String, crate::scanning::check_dom_verification::DomVerifyEvidenceOutcome>,
}

/// Grow speculative batches gradually: early catalog hits should not cost a
/// full worker window. Failed prefixes still ramp up to the existing ceiling.
/// Keep the old boundaries (1, 1 + concurrency, ...) so reaching a given hit
/// or early-exit budget never sends more requests than the full-window scheme.
fn payload_chunk_size(completed: usize, concurrency: usize) -> usize {
    if completed == 0 {
        return 1;
    }
    let concurrency = concurrency.max(1);
    let remaining_in_window = concurrency - (completed - 1) % concurrency;
    completed.saturating_add(1).min(remaining_in_window)
}

/// Shared, cheaply-clonable context handed to each spawned worker. Every
/// field is an `Arc`/handle, so `clone()` per worker is just a refcount
/// bump (plus a `ProgressBar` clone, itself an `Arc` internally).
#[derive(Clone)]
struct ScanWorkerCtx {
    args: Arc<ScanArgs>,
    target: Arc<Target>,
    client: Arc<reqwest::Client>,
    results: Arc<Mutex<Vec<crate::scanning::result::Result>>>,
    found_params: Arc<RwLock<FoundParams>>,
    findings_count: Arc<AtomicUsize>,
    pb: Option<ProgressBar>,
    overall_pb: Option<Arc<indicatif::ProgressBar>>,
    cancel: Option<Arc<std::sync::atomic::AtomicBool>>,
    finding_tx: Option<tokio::sync::mpsc::UnboundedSender<crate::scanning::result::Result>>,
    /// Per-parameter worker slot: one permit per param, held for the whole
    /// param, so at most `workers` parameters are scanned at once.
    semaphore: Arc<Semaphore>,
    /// Global per-*request* budget: every payload request acquires one permit
    /// for its duration, so the total number of concurrent HTTP requests across
    /// the whole scan is bounded by `workers` — while letting a single
    /// parameter fan its payloads out across the budget (within-parameter
    /// concurrency) instead of sending them strictly one at a time.
    req_budget: Arc<Semaphore>,
    /// Live per-parameter completion counter (see `run_scanning`'s
    /// `params_done`). Bumped once per finished parameter worker.
    params_done: Option<Arc<AtomicU32>>,
}

impl ScanWorkerCtx {
    /// True when a cancellation flag was supplied and is now set.
    fn cancelled(&self) -> bool {
        self.cancel
            .as_ref()
            .is_some_and(|c| c.load(Ordering::Relaxed))
    }

    /// True when a global `--limit` was supplied and the running findings
    /// tally has reached it.
    fn limit_reached(&self) -> bool {
        self.args
            .limit
            .is_some_and(|lim| self.findings_count.load(Ordering::Relaxed) >= lim)
    }

    /// [`Self::limit_reached`] for the per-payload phase loops. Under a
    /// `--limit`, first publish this parameter's batched findings: they only
    /// count once flushed, so `--deep-scan` (one finding per reflecting
    /// payload) could otherwise run a whole catalog — on every concurrent
    /// parameter — past the limit before any of it was seen. Without a limit
    /// the batching is left alone.
    async fn limit_reached_in_phase(&self, state: &mut ParamScanState) -> bool {
        if self.args.limit.is_some() {
            self.flush_results(&mut state.local_results).await;
        }
        self.limit_reached()
    }

    /// How many payload requests this parameter may keep in flight at once.
    ///
    /// Several modes stay strictly sequential (return 1) because concurrency
    /// would violate their contract:
    /// * `--sxss` — stored-write ordering, per-URL retrieval retries, and the
    ///   propagation backoff all assume one request at a time.
    /// * `--waf-evasion` — its whole point is a slow, jittered, *non-bursty*
    ///   cadence a WAF can't fingerprint; firing 50 requests at once is the
    ///   opposite of that.
    /// * `--delay > 0` — the documented meaning is a pause *between* requests, so
    ///   a serial cadence is what the operator asked for. (`--rate-limit` needs
    ///   no such guard: it is a scan-wide token bucket that bounds the aggregate
    ///   rate regardless of how many requests are in flight.)
    ///
    /// Otherwise a parameter fans out up to `workers` requests, capped by
    /// [`crate::cmd::scan::MAX_PER_PARAM_CONCURRENCY`] so one hard-filter
    /// parameter can't monopolise the whole budget. The global `req_budget`
    /// semaphore still bounds the scan-wide total, so this is only a per-param
    /// ceiling, never an addition to it.
    fn request_concurrency(&self) -> usize {
        if self.args.sxss || self.args.waf_evasion || self.target.delay > 0 {
            return 1;
        }
        self.target
            .workers
            .clamp(1, crate::cmd::scan::MAX_PER_PARAM_CONCURRENCY)
    }

    /// Run one payload's reflection request under the global per-request budget.
    /// Pure I/O — no shared mutable state — so a chunk of these can be awaited
    /// concurrently and their results processed serially afterwards.
    ///
    /// Returns the injection status alongside the classified reflection so the
    /// reflection phase's transformed-inert-echo budget can exclude 4xx block
    /// pages (see [`check_reflection::check_reflection_with_response`]).
    async fn fetch_reflection(
        &self,
        param: &Param,
        payload: &str,
        waf_streak: &std::sync::atomic::AtomicU32,
        want_dom: bool,
    ) -> (
        Option<check_reflection::ReflectionKind>,
        Option<check_reflection::ReflectionBody>,
        u16,
        bool,
        Option<crate::scanning::check_dom_verification::DomVerifyEvidenceOutcome>,
        bool,
    ) {
        let _permit = self.req_budget.acquire().await;
        check_reflection::check_reflection_with_dom_outcome(
            self.client.as_ref(),
            &self.target,
            param,
            payload,
