}
/// Count of a target's parameters the HTTP scan phase will actually test.
pub(crate) fn http_scannable_param_count(target: &Target) -> usize {
    target
        .reflection_params
        .iter()
        .filter(|p| param_is_http_scannable(p))
        .count()
