/// [`run_initial_ast_dom_analysis_for_response`], plus the scripts it skipped.
pub(crate) fn run_initial_ast_dom_analysis_with_skips(
    response_text: &str,
    content_type: &str,
    target_url: &str,
    target_method: &str,
    posture: PageSecurityPosture,
) -> (Vec<crate::scanning::result::Result>, AstSkips) {
    // An unmarked body: the markup only contributes element facts (form ids).
    let (js_blocks, script_element_ids, page_markup) =
        if crate::utils::is_xml_content_type(content_type) {
            let document = crate::utils::xml::parse_xml_document(response_text);
            if !crate::utils::xml::document_has_markup_for_content_type(
                content_type,
                response_text,
                &document,
            ) {
                return (Vec::new(), AstSkips::default());
            }
            let (js_blocks, script_ids) = extract_js_and_script_ids_from_xml_document(document);
            let js_blocks = js_blocks.into_iter().map(JsBlock::own).collect();
            (js_blocks, script_ids, Default::default())
        } else {
            if !crate::utils::response_has_markup_document(content_type, response_text) {
                return (Vec::new(), AstSkips::default());
            }
            extract_js_script_ids_and_reflected_markup(response_text)
        };
    // Shared across blocks: a per-block clone is O(blocks x ids).
    let (script_element_ids, page_markup) = (Arc::new(script_element_ids), Arc::new(page_markup));
    let mut out: Vec<crate::scanning::result::Result> = Vec::new();
    let mut skips = AstSkips::default();
    // The page's classic scripts share one global scope, in this order.
    let mut page_globals = crate::scanning::ast_dom_analysis::CarriedGlobals::new();
    for block in js_blocks {
        let mut own_globals = Default::default();
        let Some(globals) = block.globals(&mut page_globals, &mut own_globals) else {
            continue;
        };
        let repeat = block.is_repeat();
        let js_code = block.code;
        let findings = analyze_javascript_for_dom_xss_with_html_context(
            &js_code,
            &script_element_ids,
            &page_markup,
            posture.trusted_types_enforced,
            globals,
        );
        if repeat {
            continue;
        }
        skips.record(&js_code);
        // Normalized once per block, not once per finding.
        let mut normalized_js: Option<String> = None;
        for (vuln, payload, description) in findings {
            let normalized_js =
                normalized_js.get_or_insert_with(|| normalize_js_for_pattern_matching(&js_code));
            let self_bootstrap_verified =
                has_self_bootstrap_verification_normalized(normalized_js, &vuln.source);
            let message = if let Some(hint) =
                build_dom_xss_manual_poc_hint(target_url, &vuln.source, &payload)
            {
                format!("{description} (needs runtime confirmation) [manual POC: {hint}]")
            } else {
                // URL-carried sources need no setup hint — the POC URL on the
                // finding is the reproduction step. The old
                // `[light check: no parameter]` suffix here was internal
                // wording that read like a scan result (#1238).
                format!("{description} (needs runtime confirmation)")
            };
            let evidence = format!(
                "{}:{}:{} - {} (Source: {}, Sink: {})",
                target_url, vuln.line, vuln.column, description, vuln.source, vuln.sink
            );
            out.push(build_ast_dom_xss_result(AstDomFinding {
                target_url,
                target_method,
                vuln: &vuln,
                payload,
                evidence,
                message,
                self_bootstrap_verified,
                posture,
            }));
        }
    }
    (out, skips)
}

