    pub fn param(mut self, v: impl Into<String>) -> Self {
        self.inner.param = v.into();
        self
    }

    /// The payload that triggered the finding.
    pub fn payload(mut self, v: impl Into<String>) -> Self {
        self.inner.payload = v.into();
        self
