                    // above) so window-pad / base64 / multi-URL findings
                    // reproduce.
                    let poc_payload =
                        crate::encoding::pre_encoding::apply_param_encoding(dom_payload, param);
                    let result_url = crate::scanning::url_inject::build_injected_url(
                        &base,
                        param,
                        &poc_payload,
                    );

